BEGIN READ ONLY; SET LOCAL statement_timeout='5s';
SELECT b.cluster_id,b.namespace_uid,b.workload_uids,a.created_at,proof.acknowledged_at FROM permission_basis b JOIN permission_stream s ON s.id=b.stream_id JOIN permission_assignment a ON a.stream_id=b.stream_id AND a.basis_key=b.basis_key JOIN authority_audit proof ON proof.id=a.activation_audit_id WHERE b.effect='Allow' AND b.seen_sequence=s.sequence AND (b.not_after IS NULL OR b.not_after>clock_timestamp()) AND a.role='workload-maintainer' AND a.retired_at IS NULL AND proof.stream_id=b.stream_id AND proof.acknowledged_at IS NOT NULL LIMIT 20; COMMIT;